27	const PROCESSING_FEE = 5;
28	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	};
35	
36	// Kept as an exact fraction rather than `amount * 1.1`, which drifts in
37	// floating point (100 * 1.1 === 110.00000000000001).
38	const withFirstInsuranceSurcharge = (amount: number): number =>
39	  (amount * 11) / 10;
40	
41	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
42	  const results = scenario.steps.map((step) => {
43	    const policyBasePremium = step.items.reduce(
44	      (sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type],
45	      0,
46	    );
47	    const premium =
48	      withFirstInsuranceSurcharge(policyBasePremium) + PROCESSING_FEE;
49	    return { premium };
50	  });
51	
52	  return { results };
53	};
